def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Calculate the RSI for RSI(6)
    def rsi(series, n=6):
        avg_gain = series[1:].rolling(window=n).mean()
        avg_loss = series[1:].rolling(window=n).mean()
        rsi_values = 100 - 100 / (1 + avg_gain / avg_loss)
        rsi_values[avg_loss == 0] = 100
        return rsi_values

    # Initialize the position series
    position = pd.Series(0, index=df.index)

    # Calculate the RSI for RSI(6)
    rsi_6 = rsi(df['close'])

    # Iterate over each bar to determine the position
    for i in range(len(df)):
        if position[i-1] == 0:
            # Flat
            if rsi_6[i] < 28:
                position[i] = 1
            else:
                position[i] = 0
        else:
            # Long
            if rsi_6[i] > 45:
                position[i] = 0
            else:
                position[i] = position[i-1]

    return position

