    # Calculate the Relative Strength Index (RSI) of the last 4 closing prices
    df['RSI_4'] = df['close'].rolling(window=4).apply(lambda x: x / x.shift(1) - 1)

    # Initialize the position series with 0
    position = pd.Series(0, index=df.index)

    # Calculate the position based on the conditions
    for i in range(len(df)):
        if position.iat[i-1] == 0:
            # Flat
            if df['close'].iat[i] > df['SMA_60'].iat[i] and df['RSI_4'].iat[i] < 40:
                position.iat[i] = 1
            else:
                position.iat[i] = position.iat[i-1]
        else:
            # Long
            if df['RSI_4'].iat[i] > 55 or df['close'].iat[i] < df['SMA_60'].iat[i]:
                position.iat[i] = 0
            else:
                position.iat[i] = position.iat[i-1]

    return position

