def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Calculate the Simple Moving Average (SMA) of the last 60 closing prices
    sma_60 = df['close'].rolling(window=60).mean()

    # Calculate the Relative Strength Index (RSI) of the last 7 closing prices
    rsi_7 = df['close'].rolling(window=7).apply(lambda x: 100 - 100 / (1 + x.mean() / x.mean()))

    # Initialize the position series with 0
    position = pd.Series(0, index=df.index)

    # Calculate the position based on the conditions
    for i in range(len(df)):
        if position.iat[i-1] == 0:
            # Flat
            if df['close'].iat[i] > sma_60.iat[i-1] and rsi_7.iat[i] < 40:
                position.iat[i] = 1
            elif df['close'].iat[i] < sma_60.iat[i-1] and rsi_7.iat[i] > 60:
                position.iat[i] = -1
        else:
            # Long
            if rsi_7.iat[i] > 55 or df['close'].iat[i] < sma_60.iat[i-1]:
                position.iat[i] = 0
            elif rsi_7.iat[i] < 45 or df['close'].iat[i] > sma_60.iat[i-1]:
                position.iat[i] = -1
        # Ensure the position is within the range of -1, 0, 1
        position.iat[i] = max(min(position.iat[i], 1), -1)

    return position

