    sma_25 = df['close'].rolling(window=25).mean()

    # Initialize the position series with 0
    position = pd.Series(0, index=df.index)

    # Initialize the peak variable with the first bar
    peak = df['close'].iloc[0]

    # Initialize the trough variable with the first bar
    trough = df['close'].iloc[0]

    # Iterate over each bar to determine the position
    for i in range(len(df)):
        if position.iloc[i] == 0:
            # Flat, go long when close crosses above SMA(25)
            if df['close'].iloc[i] > sma_25.iloc[i-1]:
                position.iloc[i] = 1
                peak = df['close'].iloc[i]
            # Flat, go short when close crosses below SMA(25)
            elif df['close'].iloc[i] < sma_25.iloc[i-1]:
                position.iloc[i] = -1
                trough = df['close'].iloc[i]
        else:
            # Position is open, track peak and trough
            if position.iloc[i] == 1:
                # Long, track peak
                if df['close'].iloc[i] > peak:
                    peak = df['close'].iloc[i]
                # Exit to flat when close < peak * (1 - 0.07)
                if df['close'].iloc[i] < peak * (1 - 0.07):
                    position.iloc[i] = 0
            elif position.iloc[i] == -1:
                # Short, track trough
                if df['close'].iloc[i] < trough:
                    trough = df['close'].iloc[i]
                # Exit to flat when close > trough * (1 + 0.07)
                if df['close'].iloc[i] > trough * (1 + 0.07):
                    position.iloc[i] = 0

    return position

